import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport 'package:aldjawal_travel_app/constants/app_colors.dart';\nimport 'package:aldjawal_travel_app/constants/app_strings.dart';\nimport 'package:aldjawal_travel_app/models/budget_recommendation.dart';\nimport 'package:aldjawal_travel_app/providers/locale_provider.dart';\nimport 'package:aldjawal_travel_app/services/budget_recommendation_service.dart';\n\nclass BudgetPlannerScreen extends StatefulWidget {\n  const BudgetPlannerScreen({Key? key}) : super(key: key);\n\n  @override\n  State<BudgetPlannerScreen> createState() => _BudgetPlannerScreenState();\n}\n\nclass _BudgetPlannerScreenState extends State<BudgetPlannerScreen> {\n  final TextEditingController _budgetController = TextEditingController();\n  final TextEditingController _daysController = TextEditingController();\n  \n  String _selectedPassport = 'DZ';\n  List<BudgetRecommendation> _recommendations = [];\n  bool _isLoading = false;\n  String? _errorMessage;\n\n  final BudgetRecommendationService _budgetService =\n      BudgetRecommendationService(baseUrl: 'https://your-api.example.com');\n\n  @override\n  void initState() {\n    super.initState();\n    _daysController.text = '7';\n  }\n\n  /// Fetch recommendations based on budget and days\n  Future<void> _fetchRecommendations() async {\n    if (_budgetController.text.isEmpty) {\n      setState(() {\n        _errorMessage = 'Please enter a budget amount';\n      });\n      return;\n    }\n\n    final budget = double.tryParse(_budgetController.text);\n    final days = int.tryParse(_daysController.text) ?? 7;\n\n    if (budget == null || budget <= 0) {\n      setState(() {\n        _errorMessage = 'Invalid budget amount';\n      });\n      return;\n    }\n\n    setState(() {\n      _isLoading = true;\n      _errorMessage = null;\n    });\n\n    try {\n      final recommendations = await _budgetService.getAffordableDestinations(\n        passportCode: _selectedPassport,\n        budgetUSD: budget,\n        estimatedDays: days,\n      );\n\n      setState(() {\n        _recommendations = recommendations;\n        _isLoading = false;\n      });\n    } catch (e) {\n      setState(() {\n        _errorMessage = 'Failed to fetch recommendations: $e';\n        _isLoading = false;\n      });\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final localeProvider = Provider.of<LocaleProvider>(context);\n    final strings = AppStrings.get(localeProvider.currentLocale);\n    final isArabic = localeProvider.isArabic;\n\n    return Scaffold(\n      appBar: AppBar(\n        backgroundColor: AppColors.darkNavy,\n        title: const Text(\n          'Budget Planner',\n          style: TextStyle(fontWeight: FontWeight.bold),\n        ),\n      ),\n      body: SingleChildScrollView(\n        child: Padding(\n          padding: const EdgeInsets.all(16),\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              // Budget Input Section\n              _buildInputCard(\n                title: isArabic ? 'ميزانيتك 💰' : 'Your Budget 💰',\n                children: [\n                  // Passport Selection\n                  Text(\n                    isArabic ? 'اختر جوازك:' : 'Select Passport:',\n                    style: const TextStyle(\n                      color: Colors.grey,\n                      fontSize: 12,\n                    ),\n                  ),\n                  const SizedBox(height: 8),\n                  Row(\n                    children: [\n                      _buildPassportChip('🇩🇿 DZ', 'DZ'),\n                      const SizedBox(width: 12),\n                      _buildPassportChip('🇫🇷 FR', 'FR'),\n                    ],\n                  ),\n                  const SizedBox(height: 20),\n\n                  // Budget Amount Input\n                  TextField(\n                    controller: _budgetController,\n                    keyboardType: TextInputType.number,\n                    style: const TextStyle(color: Colors.white),\n                    decoration: InputDecoration(\n                      hintText: isArabic ? 'أدخل الميزانية بالدولار' : 'Enter budget in USD',\n                      hintStyle: TextStyle(color: Colors.grey.withOpacity(0.5)),\n                      prefixIcon: const Icon(Icons.attach_money,\n                          color: AppColors.orange),\n                      border: OutlineInputBorder(\n                        borderRadius: BorderRadius.circular(12),\n                        borderSide: const BorderSide(color: AppColors.orange),\n                      ),\n                      focusedBorder: OutlineInputBorder(\n                        borderRadius: BorderRadius.circular(12),\n                        borderSide: const BorderSide(\n                          color: AppColors.orange,\n                          width: 2,\n                        ),\n                      ),\n                    ),\n                  ),\n                  const SizedBox(height: 16),\n\n                  // Duration Input\n                  TextField(\n                    controller: _daysController,\n                    keyboardType: TextInputType.number,\n                    style: const TextStyle(color: Colors.white),\n                    decoration: InputDecoration(\n                      hintText: isArabic ? 'عدد الأيام' : 'Number of days',\n                      hintStyle: TextStyle(color: Colors.grey.withOpacity(0.5)),\n                      prefixIcon: const Icon(Icons.calendar_today,\n                          color: AppColors.orange),\n                      border: OutlineInputBorder(\n                        borderRadius: BorderRadius.circular(12),\n                        borderSide: const BorderSide(color: AppColors.orange),\n                      ),\n                      focusedBorder: OutlineInputBorder(\n                        borderRadius: BorderRadius.circular(12),\n                        borderSide: const BorderSide(\n                          color: AppColors.orange,\n                          width: 2,\n                        ),\n                      ),\n                    ),\n                  ),\n                  const SizedBox(height: 20),\n\n                  // Search Button\n                  SizedBox(\n                    width: double.infinity,\n                    child: ElevatedButton(\n                      style: ElevatedButton.styleFrom(\n                        backgroundColor: AppColors.orange,\n                        padding: const EdgeInsets.symmetric(vertical: 14),\n                        shape: RoundedRectangleBorder(\n                          borderRadius: BorderRadius.circular(12),\n                        ),\n                      ),\n                      onPressed: _isLoading ? null : _fetchRecommendations,\n                      child: _isLoading\n                          ? const SizedBox(\n                              height: 20,\n                              width: 20,\n                              child: CircularProgressIndicator(\n                                strokeWidth: 2,\n                                valueColor: AlwaysStoppedAnimation<Color>(\n                                  Colors.white,\n                                ),\n                              ),\n                            )\n                          : Text(\n                              isArabic ? 'ابحث عن الدول' : 'Find Destinations',\n                              style: const TextStyle(\n                                color: Colors.white,\n                                fontWeight: FontWeight.bold,\n                                fontSize: 16,\n                              ),\n                            ),\n                    ),\n                  ),\n                ],\n              ),\n              const SizedBox(height: 20),\n\n              // Error Message\n              if (_errorMessage != null)\n                Container(\n                  padding: const EdgeInsets.all(12),\n                  decoration: BoxDecoration(\n                    color: Colors.red.withOpacity(0.1),\n                    borderRadius: BorderRadius.circular(12),\n                    border: Border.all(\n                      color: Colors.red.withOpacity(0.3),\n                    ),\n                  ),\n                  child: Row(\n                    children: [\n                      const Icon(Icons.error_outline, color: Colors.red),\n                      const SizedBox(width: 12),\n                      Expanded(\n                        child: Text(\n                          _errorMessage!,\n                          style: const TextStyle(\n                            color: Colors.redAccent,\n                            fontSize: 13,\n                          ),\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n\n              if (_errorMessage != null) const SizedBox(height: 20),\n\n              // Results Section\n              if (_recommendations.isNotEmpty) ...\n                [\n                  Text(\n                    isArabic\n                        ? 'الدول المتاحة (${_recommendations.length})'\n                        : 'Available Destinations (${_recommendations.length})',\n                    style: const TextStyle(\n                      fontSize: 18,\n                      fontWeight: FontWeight.bold,\n                      color: Colors.white,\n                    ),\n                  ),\n                  const SizedBox(height: 12),\n                  ..._recommendations\n                      .map((rec) => _buildDestinationCard(rec, isArabic))\n                      .toList(),\n                ],\n\n              // Empty State\n              if (_recommendations.isEmpty && !_isLoading && _errorMessage == null)\n                Center(\n                  child: Column(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    children: [\n                      const SizedBox(height: 40),\n                      Icon(\n                        Icons.search,\n                        size: 64,\n                        color: Colors.grey.withOpacity(0.3),\n                      ),\n                      const SizedBox(height: 16),\n                      Text(\n                        isArabic\n                            ? 'أدخل ميزانيتك للبحث'\n                            : 'Enter your budget to search',\n                        style: TextStyle(\n                          color: Colors.grey.withOpacity(0.6),\n                          fontSize: 16,\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildInputCard({\n    required String title,\n    required List<Widget> children,\n  }) {\n    return Container(\n      padding: const EdgeInsets.all(16),\n      decoration: BoxDecoration(\n        color: AppColors.charcoal,\n        borderRadius: BorderRadius.circular(15),\n        border: Border.all(\n          color: AppColors.orange.withOpacity(0.2),\n        ),\n      ),\n      child: Column(\n        crossAxisAlignment: CrossAxisAlignment.start,\n        children: [\n          Text(\n            title,\n            style: const TextStyle(\n              fontSize: 16,\n              fontWeight: FontWeight.bold,\n              color: Colors.white,\n            ),\n          ),\n          const SizedBox(height: 16),\n          ...children,\n        ],\n      ),\n    );\n  }\n\n  Widget _buildPassportChip(String label, String code) {\n    return ChoiceChip(\n      label: Text(label),\n      selected: _selectedPassport == code,\n      selectedColor: AppColors.orange,\n      onSelected: (selected) {\n        if (selected) {\n          setState(() {\n            _selectedPassport = code;\n          });\n        }\n      },\n    );\n  }\n\n  Widget _buildDestinationCard(\n    BudgetRecommendation rec,\n    bool isArabic,\n  ) {\n    final countryName = isArabic ? rec.countryNameAr : rec.countryName;\n    final statusColor = rec.remainingBudget >= 0\n        ? AppColors.successGreen\n        : AppColors.errorRed;\n\n    return Card(\n      color: AppColors.charcoal,\n      margin: const EdgeInsets.only(bottom: 12),\n      shape: RoundedRectangleBorder(\n        borderRadius: BorderRadius.circular(15),\n        side: BorderSide(\n          color: statusColor.withOpacity(0.3),\n        ),\n      ),\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // Country Name & Status\n            Row(\n              mainAxisAlignment: MainAxisAlignment.spaceBetween,\n              children: [\n                Expanded(\n                  child: Text(\n                    countryName,\n                    style: const TextStyle(\n                      fontSize: 16,\n                      fontWeight: FontWeight.bold,\n                      color: Colors.white,\n                    ),\n                  ),\n                ),\n                Container(\n                  padding: const EdgeInsets.symmetric(\n                    horizontal: 10,\n                    vertical: 4,\n                  ),\n                  decoration: BoxDecoration(\n                    color: rec.affordabilityRating == 'Budget'\n                        ? AppColors.successGreen.withOpacity(0.2)\n                        : AppColors.orange.withOpacity(0.2),\n                    borderRadius: BorderRadius.circular(8),\n                  ),\n                  child: Text(\n                    rec.affordabilityRating,\n                    style: TextStyle(\n                      color: rec.affordabilityRating == 'Budget'\n                          ? AppColors.successGreen\n                          : AppColors.orange,\n                      fontSize: 11,\n                      fontWeight: FontWeight.bold,\n                    ),\n                  ),\n                ),\n              ],\n            ),\n            const SizedBox(height: 12),\n\n            // Breakdown\n            _buildCostRow(\n              isArabic ? '✈️ الطيران' : '✈️ Flights',\n              '\\$${rec.flightCost.toStringAsFixed(0)}',\n            ),\n            _buildCostRow(\n              isArabic ? '🏨 الفندق/الليلة' : '🏨 Hotel/Night',\n              '\\$${rec.hotelCostPerNight.toStringAsFixed(0)}',\n            ),\n            _buildCostRow(\n              isArabic ? '💵 التأشيرة' : '💵 Visa',\n              '\\$${rec.visaFee.toStringAsFixed(0)}',\n            ),\n            const Divider(color: Colors.grey),\n\n            // Total & Remaining\n            _buildCostRow(\n              isArabic ? 'المجموع المقدر' : 'Estimated Total',\n              '\\$${rec.estimatedTotalCost.toStringAsFixed(0)}',\n              isBold: true,\n            ),\n            _buildCostRow(\n              isArabic ? 'الميزانية المتبقية' : 'Remaining Budget',\n              '\\$${rec.remainingBudget.toStringAsFixed(0)}',\n              color: statusColor,\n              isBold: true,\n            ),\n            const SizedBox(height: 12),\n\n            // Additional Info\n            Container(\n              padding: const EdgeInsets.all(10),\n              decoration: BoxDecoration(\n                color: Colors.blue.withOpacity(0.1),\n                borderRadius: BorderRadius.circular(8),\n              ),\n              child: Row(\n                children: [\n                  const Icon(Icons.info_outline,\n                      color: Colors.blue, size: 16),\n                  const SizedBox(width: 8),\n                  Expanded(\n                    child: Text(\n                      isArabic\n                          ? 'تستطيع البقاء ${rec.possibleDays} يوم'\n                          : 'You can stay ${rec.possibleDays} days',\n                      style: const TextStyle(\n                        color: Colors.blue,\n                        fontSize: 12,\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildCostRow(\n    String label,\n    String value, {\n    bool isBold = false,\n    Color color = Colors.white,\n  }) {\n    return Padding(\n      padding: const EdgeInsets.symmetric(vertical: 4),\n      child: Row(\n        mainAxisAlignment: MainAxisAlignment.spaceBetween,\n        children: [\n          Text(\n            label,\n            style: TextStyle(\n              color: Colors.grey,\n              fontSize: isBold ? 13 : 12,\n              fontWeight: isBold ? FontWeight.bold : FontWeight.normal,\n            ),\n          ),\n          Text(\n            value,\n            style: TextStyle(\n              color: color,\n              fontWeight: FontWeight.bold,\n              fontSize: isBold ? 14 : 12,\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  @override\n  void dispose() {\n    _budgetController.dispose();\n    _daysController.dispose();\n    _budgetService.dispose();\n    super.dispose();\n  }\n}\n